// 教学伪代码：两种不同的对象模型
let a = value({ n: 1 }), b = copy(a);
b.n = 2; print(a.n);       // 独立值：1
let x = object({ n: 1 }), y = x;
y.n = 2; print(x.n);       // 共享身份：2

// 教学伪代码：移动与克隆是两种操作
let a = own(openFile());
let b = move(a);            // 清理责任交给 b
use(a);                    // 移动路线应拒绝
let c = clone(b);           // 只有类型提供此操作才成立
// b 与 c 的共享/独立关系必须由 clone 合同说明

// 教学伪代码：预留身份不等于可以读取
let p = reserve<Node>();
print(p.value);            // 拒绝：还没有合法 Node
initialize(p, { value: 1, next: null });
let node = publish(p);
print(node.value);         // 现在才允许

// 教学伪代码：起点在缓冲内仍可能越界
let bytes = buffer(8);
read(bytes, 4, 1);          // 读取 [4,5)，在范围内
read(bytes, 4, 8);          // 读取 [4,12)，必须拒绝
let [left, right] = splitChecked(bytes, 4);
// 两个视图只覆盖各自区间

// 教学伪代码：连接本身可以不拥有目标
let storage = ownRegion();
let a = storage.newNode();
let b = storage.newNode();
a.next = b; b.next = a;    // 连接可成环
// 保留整组的是 storage，不能仅凭 a.next 推断谁负责释放

// 教学伪代码：同一业务删除的不同回收时机
set.remove(id);             // 不再属于集合
// 方案 A：删除时立即关闭资源
// 方案 B：最后拥有者结束后关闭
// 方案 C：旧访问结束后的退役边界关闭
// 方案 D：确认不可达后再择机回收

// 教学伪代码：只留下一个入口，可能保留整域
let region = newRegion();
let nodes = repeat(1000, () => region.newNode());
let keep = nodes[0];
// keep 活着时，若共同域不能结束，其他 999 个节点也可能仍占存储

// 教学伪代码：同一段调用，取决于 remove 合同
let p = graph.get(id);
graph.remove(id);
use(p);
// unlink：由原保活方案决定是否可用
// retire：只在受保护的旧使用范围内可用
// invalidate：应静态拒绝，或重新 resolve 并处理失败

// 教学伪代码：槽号相同，不保证还是同一对象
let old = pool.insert({ name: "A" }); // 某个身份
pool.remove(old);
let now = pool.insert({ name: "B" }); // 可能复用原槽
resolve(old);              // 必须失败或已被禁止使用，不能变成 B
resolve(now);              // 才能得到 B

// 教学伪代码：保留父对象不保留旧缓冲地址
let list = vector([1, 2, 3]);
let view = borrowSlice(list);
list.grow(10000);           // 若会搬旧缓冲，活动 view 必须阻止它
print(view[0]);             // 不能靠 list 还活着来证明安全

// 教学伪代码：同一对象的两个入口
let a = node, b = node;
a.count += 1; b.count += 1; // 可以是合法的顺序短操作
let p = borrowMut(a.count);
b.count += 1;              // p 活动时的相交写必须按协议排除
callback();               // 还要检查回调是否会访问同一范围

// 教学伪代码：两个 helper 是否真的冲突？
let view = borrow(engine.messages);
record(engine.stats, "seen"); // 只写 stats，可能与 view 共存
recordAll(engine);           // 若接口只暴露整对象写，必须保守
// 改 helper 正文去写 messages 后，原不交结论必须失效

// 教学伪代码：来源关系约束使用，不延长目标生命
function choose(a, b, first) -> View from(a, b) {
  return first ? view(a) : view(b);
}
let x = choose(longLived, shortLived, flag);
// x 的每次使用都必须被它可能依赖的来源覆盖
// 不能返回局部临时地址后，仅写 from 就让临时对象继续活着

// 教学伪代码：三条访问路线
read(borrowProven(node));   // 已有静态依据
with (pool.resolve(key)) { p => read(p); } // 准入并保护
unsafeRead(rawAddress);    // 调用者承担完整合同
// resolve 成功后若已解除保护，不能继续把裸地址当作安全结果

// 教学伪代码：显式错误不等于回滚
function transfer(a, b, n) -> Result {
  a.balance -= n;
  if (!canCredit(b)) return Error("blocked");
  b.balance += n;
  return Ok();
}
// 失败时 a 已经扣款；要原子性还需 prepare/commit 等协议

// 教学伪代码：字段相同也可能不兼容
type UserId  = { value: number };
type OrderId = { value: number };
function loadUser(id: UserId) {}
loadUser(orderId);
// 名义路线：可要求不同类型不能混用
// 结构路线：若可见约束相同，可能直接兼容

// 教学伪代码：泛型不能无来源地获得能力
function speak<T>(x: T) { x.speak(); }
// 按约束检查：需要 T: Speaker 等依据
// 按实例检查：实例的 T 必须真有合法 speak
// 即使正文已按 Speaker 检查，Dog/Cat 仍可能需要不同机器代码

// 教学伪代码：同样写 x.speak()
speakKnownDog(dog);             // 目标已确定
let call = runtimeChoose();
call(data);                    // 函数指针
let view = { data, table };
view.table.speak(view.data);    // 接口表

// 教学伪代码：相同大小不表示同一机器工作
function plusOne<T>(x: T) { return x + 1; }
plusOne<Int32>(x);          // 整数运算及其溢出规则
plusOne<Float32>(y);        // 浮点运算
// 都可能占 4 字节，仍不能仅凭大小合并
// 只读取一个统一长度字段的正文，则可能有更多共享机会

// 教学伪代码：保存和调用必须分开
function lazyMap(items, f) { return { items, f }; }
let seq = lazyMap(data, x => writeFile(x));
// 构造 seq 要保留 data/f 的依赖，但尚未执行 writeFile
next(seq);                 // 这里才真正承担调用 f 的效果
drop(seq);                 // 清理实际拥有字段，不等于调用 f

// 教学伪代码：立即借用与长期保存
let config = localConfig();
forEach(items, x => use(config, x)); // 若不逃逸，可借 config
registry.save(x => use(config, x));  // 必须让捕获及依赖覆盖保存期
// 不能把第二行降成指向短命调用栈的环境地址

// 教学伪代码：业务相同，等待表示可不同
function readPair(io, a, b) {
  let x = io.read(a);
  let y = io.read(b);
  return combine(x, y);
}
// 阻塞：线程等；有栈：保留任务栈；状态机：保存 x 等活跃状态
// 选择表示不能抹掉真实的等待和存储

// 教学伪代码：取消请求不等于使用结束
let op = device.startWrite(buffer);
op.requestCancel();
free(buffer);              // 此时可能仍被设备读取，应禁止
await op.reap();            // 协议确认不再使用
free(buffer);              // 且满足其他依赖后才允许

// 教学伪代码：调用返回了，外部使用未必结束
extern function submit(ptr, len, callback);
submit(buffer.ptr, buffer.len, onDone);
// 如果 submit 保存 ptr，buffer 必须覆盖外部实际使用期
// 不能仅凭 submit 已返回就释放 buffer
// onDone 是否表示真正完成，也要由协议明确

// 教学伪代码：生成代码仍要检查
generate("function bad() { return borrow(localTemp()); }");
// 即使语法生成成功，返回短命局部借用仍必须按正常规则处理
macro twice(expr) { expr + expr }
// 若 expr 有副作用，还要说明它是否被执行两次

// 教学伪代码：不同变化影响不同消费者
old: function count(x) -> number { return slowCount(x); }
new: function count(x) -> number { return fastCount(x); }
// 定义方必须重查；若合同和 ABI 不变，普通调用者可能复用
// 内联了旧正文、在 comptime 调用了它的消费者仍有实现依赖

// 教学伪代码：两种未证明必须分开
proveAlive(p);              // 必需证据：未完成则不能授予安全读取
proveIndexInside(i, n);     // 若动态边界检查本来就是合法后备
// 删检查证明失败：保留 if (i >= n) fail()
// 泛型求解超限：报告 ResourceLimit，不把它缓存成“没有实现”
